import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { readFileSync } from "node:fs";
import type http from "node:http";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { buildMcpServer, SERVER_NAME } from "../src/mcpServer.js";
import { createApp } from "../src/http.js";

// SERVER_VERSION lives in src/version.ts, generated by
// scripts/sync-server-version.mjs. These tests check what a client actually
// sees in initialize, so they also catch a hardcoded version creeping back in.
const pkgVersion: string = JSON.parse(
  readFileSync(new URL("../package.json", import.meta.url), "utf8"),
).version;

describe("server version in initialize", () => {
  it("the shared server builder reports package.json's version", async () => {
    const server = buildMcpServer({ apiKey: "test" });
    const client = new Client({ name: "version-test", version: "1.0.0" });
    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([server.connect(serverTransport), client.connect(clientTransport)]);

    expect(client.getServerVersion()).toEqual({ name: SERVER_NAME, version: pkgVersion });

    await client.close();
  });

  describe("hosted HTTP app", () => {
    let listener: http.Server;

    beforeAll(() => {
      listener = createApp().listen(0);
    });

    afterAll(async () => {
      listener.closeAllConnections();
      await new Promise<void>((resolve) => listener.close(() => resolve()));
    });

    it("reports package.json's version", async () => {
      const { port } = listener.address() as { port: number };
      const res = await fetch(`http://127.0.0.1:${port}/`, {
        method: "POST",
        headers: {
          Authorization: "Bearer test",
          "Content-Type": "application/json",
          Accept: "application/json, text/event-stream",
        },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "initialize",
          params: {
            protocolVersion: "2025-06-18",
            capabilities: {},
            clientInfo: { name: "version-test", version: "1.0.0" },
          },
        }),
      });
      const text = await res.text();
      expect(res.status, text).toBe(200);

      // The streamable HTTP transport may answer as plain JSON or as SSE.
      const payload = text.trimStart().startsWith("{")
        ? text
        : text.split("\n").find((l) => l.startsWith("data:"))?.slice("data:".length);
      expect(payload, `no JSON-RPC payload in response: ${text}`).toBeDefined();
      expect(JSON.parse(payload!).result.serverInfo).toEqual({
        name: SERVER_NAME,
        version: pkgVersion,
      });
    });
  });
});
